import { recallTiered } from './epistemic-vault.mjs';
import { callGroqDirect } from './openjarvis.mjs';
import fs from 'fs';

/**
 * Meta-cognitive self-correction loop.
 * Evaluates the draft response against active SQLite truth claims.
 * If a contradiction or lie is detected, it self-corrects the draft before output.
 * 
 * @param {string} botName - The name of the bot generating the response.
 * @param {string} draftResponse - The raw output generated by the LLM.
 * @param {string} userId - The Discord numeric snowflake ID or speaker name.
 * @returns {Promise<string>} The corrected response or the original draft response.
 */
export async function recursiveSelfCorrection(botName, draftResponse, userId = 'system', opts = {}) {
  // Bypassing trivial, ultra-short greetings to save API overhead and latencies
  if (!draftResponse || draftResponse.length < 25) {
    return draftResponse;
  }
  // Skip reflection in social chat — the bots' personas are SUPPOSED to be
  // sharp/sarcastic/blunt and the 8B mirror sub-agent flattens them to PR voice.
  // Reflection only catches factual contradictions, which is a work-channel
  // concern, not a social-banter concern.
  if (opts.isSocial) {
    return draftResponse;
  }

  const groqKey = process.env.GROQ_API_KEY;
  if (!groqKey) {
    return draftResponse; // Safe fallback if no key is configured
  }

  try {
    // 1. Recall relevant truth claims from the Epistemic Vault (SQLite)
    // We search the database using the draft response content as the semantic query
    const relatedCells = recallTiered(userId, draftResponse.slice(0, 100), 5);
    
    if (relatedCells.length === 0) {
      return draftResponse; // No stored claims to compare against; pass cleanly
    }

    // Format the active truth claims for the mirror sub-agent
    const claimsBlock = relatedCells.map((c, i) => {
      const category = c.category ? `[${c.category.toUpperCase()}]` : '';
      return `${i + 1}. ${category} Claim: "${c.summary || c.content}" (Confidence: ${c.confidence})`;
    }).join('\n');

    console.log(`[Self-Reflection/${botName}] Evaluating draft against ${relatedCells.length} truth claims...`);

    // 2. Spawn a fast mirror sub-agent to audit the draft
    const systemPrompt = `You are KAI's cognitive supervisor and self-reflection mirror node in the RSHL ecosystem.
Your sole job is to protect KAI and its specialized agents from breaking character, contradicting historical facts, lying, or presenting false technical claims.

Here are the active, verified TRUTH CLAIMS stored in the Epistemic Vault:
${claimsBlock}

Evaluate the DRAFT RESPONSE.
- Check if it flatly contradicts, negates, or ignores any of the verified claims.
- If it contradicts or fabricates facts relative to the claims, output "[REJECT]" followed immediately on the next line by a corrected, refined version of the response that respects the truth claims, matching the tone and style of ${botName}.
- If the response is completely consistent with all claims, output "[PASS]".

Be extremely precise. Do not output conversational filler. Output only "[PASS]" or "[REJECT]\\n<corrected response>".`;

    const auditResult = await callGroqDirect(
      botName,
      `DRAFT RESPONSE:\n"${draftResponse}"`,
      systemPrompt,
      'llama-3.1-8b-instant',
      1000
    );

    if (auditResult && auditResult.includes('[REJECT]')) {
      const correctedLines = auditResult.replace('[REJECT]', '').trim();
      if (correctedLines.length > 5) {
        // Log to stdout (console.log) not stderr — the reflection working as
        // designed is not a system error and shouldn't trigger Oracle's
        // SYSTEM_ERROR → Kai Coder auto-repair pipeline.
        console.log(`[Self-Reflection/${botName}] Corrected draft: "${draftResponse.slice(0, 60)}..." -> "${correctedLines.slice(0, 60)}..."`);
        
        // Log the self-correction event for performance and auditing
        try {
          fs.appendFileSync(
            'c:/KAI/tools/oracle-discord/logs/ecosystem.log',
            `[${new Date().toISOString()}] [Self-Reflection/${botName}] REJECTED & CORRECTED draft response to user ${userId}.\nOriginal: ${draftResponse}\nCorrected: ${correctedLines}\n`
          );
        } catch (le) {}

        return correctedLines;
      }
    }

    // Default to the original draft response if it passes or audit is inconclusive
    return draftResponse;
  } catch (e) {
    console.error(`[Self-Reflection/${botName}] Error in recursive mirror loop:`, e.message);
    return draftResponse; // Fallback safely to keep chat fluid
  }
}
